// Export the arcade events (names, category, planet, track, laps, medal times) as JSON, for the community website.
//   node src/scripts/export-events.js [out.json]      (default: arcade-events.json in the current directory)
// Game data from src/data/swgr (generated by tools/import_swgr.py); ids match the times/ and staff/ boards in the
// database (target = event id). Laps follow the cards: only loop tracks have them (none for point-to-point runs).
const fs = require('node:fs')
const data = require('../swgr/data.js')

const out = process.argv[2] || 'arcade-events.json'
const events = data.events.map(e => {
    const track = data.track(e.track), planet = data.planet(e.planet)
    return {
        id: e.id,
        order: e.order,
        name: e.name,
        category: e.category,
        main: e.category != 'Deluxe',  // the 50 main events the cumulative leaderboard sums (the Deluxe pack is extra)
        mode: e.mode,
        description: e.description,
        planet: { id: planet.id, name: planet.name },
        track: { id: track.id, name: track.name, format: track.format },
        laps: track.format == 'Loop' ? e.laps ?? null : null,
        direction: e.direction ?? null,  // null = Forward (or a route with no direction); else Reverse / Rally
        condition: e.condition ?? null,
        vehicleClass: e.vehicleClass,
        vehicle: e.vehicle,
        medals: Object.fromEntries(['gold', 'silver', 'bronze'].map(m => [m, { seconds: e.medals[m].seconds, time: e.medals[m].time, rival: e.medals[m].rival }])),
    }
})
const doc = {
    generated: new Date().toISOString(),
    notes: 'Times in seconds (format to 2 decimals); medal "time" is as the game shows it. Event ids are the database\'s board targets (times/ and staff/, kind "arcade"). Game data from STAR WARS: Galactic Racer, property of its owners.',
    categories: data.categories.map(c => ({ id: c.id, name: c.name, main: c.id != 'Deluxe', events: events.filter(e => e.category == c.id).map(e => e.id) })),
    events,
}
fs.writeFileSync(out, JSON.stringify(doc, null, 2) + '\n')
console.log(`${events.length} events in ${doc.categories.length} categories -> ${out}`)
